12	// 本文件回归“成功执行必须包含实际动作”在读取路径上的判定：无动作提案被
13	// 写成 executed、再配一份动作列表为空（或缺失/为 null）的执行凭据时，
14	// 即使凭据编号、执行时间、成功序号合法且余额能够核对一致，也必须判整份
15	// 状态文件损坏，而不是被当成一次成功执行记录接受。
16	
17	// writeStateDoc 把结构化状态文档写入临时状态文件，供手工构造“应用自身
18	// 永远不会写出”的损坏内容（如 executed 无动作提案 + 空动作凭据）。
19	func writeStateDoc(t *testing.T, path string, doc map[string]any) {
20		t.Helper()
21		raw, err := json.MarshalIndent(doc, "", "  ")
22		if err != nil {
23			t.Fatal(err)
24		}
25		raw = append(raw, '\n')
26		if err := os.WriteFile(path, raw, 0o600); err != nil {
27			t.Fatal(err)
28		}
29	}
30	
31	// emptyReceiptTaskDoc 构造任务描述的典型损坏文件：初始/当前余额均为 100、
32	// 尚无收款账户记录；登记提案 gip-empty 没有任何动作却被写成 executed，
33	// 关联凭据编号、执行时间与成功序号都合法，但动作列表为 []。
34	func emptyReceiptTaskDoc() map[string]any {
35		return map[string]any{
36			"magic":            stateMagic,
37			"version":          stateVersion,
38			"initial_treasury": float64(100),
39			"treasury":         float64(100),
40			"balances":         map[string]any{},
41			"proposals": map[string]any{
42				"gip-empty": map[string]any{
43					"id":           "gip-empty",
44					"state":        "executed",
45					"timelock_end": float64(0),
46					"actions":      []any{},
47				},
48			},
49			"receipts": []any{
50				map[string]any{
