61	// TestEmptyActionReceiptCorruptsWholeState：任务主例。空动作凭据让整份
62	// 状态文件打开失败——错误指出提案编号并说明凭据没有动作。打开失败即不
63	// 返回可用句柄，余额、提案与凭据查询都不可能得到部分结果，对该提案执行
64	// 也无从当作已完成重试；init 不覆盖损坏文件；失败后原文件逐字节保留
65	// （查询与执行在损坏内容上的逐操作拒绝见
66	// TestEmptyReceiptSpottedOnAlreadyOpenStore）。
67	func TestEmptyActionReceiptCorruptsWholeState(t *testing.T) {
68		dir := t.TempDir()
69		path := filepath.Join(dir, "treasury.json")
70		doc := emptyReceiptTaskDoc()
71		writeStateDoc(t, path, doc)
72		before, err := os.ReadFile(path)
73		if err != nil {
74			t.Fatal(err)
75		}
76	
77		s, err := Open(path)
78		if s != nil {
79			s.Close()
80		}
81		if !errors.Is(err, ErrStateCorrupt) {
82			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
83		}
84		for _, want := range []string{"receipt 0", `"gip-empty"`, "has no actions"} {
85			if !strings.Contains(err.Error(), want) {
86				t.Fatalf("error %q must contain %q", err.Error(), want)
87			}
88		}
89		// 反复打开结论一致，不会第二次“修复”或返回可用句柄。
90		if again, aerr := Open(path); again != nil || !errors.Is(aerr, ErrStateCorrupt) {
91			again.Close()
92			t.Fatalf("second Open store=%v err=%v, want nil + ErrStateCorrupt", again, aerr)
93		}
94	
95		// init 不得重建或覆盖损坏文件。
96		if _, err := InitTreasury(path, 0); !errors.Is(err, ErrTreasuryAlreadyInit) {
97			t.Fatalf("InitTreasury over corrupt file err=%v, want ErrTreasuryAlreadyInit", err)
98		}
99	
100		// 失败保留原文件：不删除空凭据、不补造转账、不把提案改回 passed。
101		after, err := os.ReadFile(path)
102		if err != nil {
103			t.Fatal(err)
104		}
105		if string(after) != string(before) {
106			t.Fatalf("corrupt file was modified")
107		}
108	}
