336	// assertWholeFileCorrupt 断言含空凭据的文件整份打不开：即使查询正常提案
337	// 或正常凭据也没有任何部分成功结果，且原文件不被改写。
338	func assertWholeFileCorrupt(t *testing.T, path, emptyID, goodID string) {
339		t.Helper()
340		raw, err := os.ReadFile(path)
341		if err != nil {
342			t.Fatal(err)
343		}
344		s, err := Open(path)
345		if !errors.Is(err, ErrStateCorrupt) {
346			if s != nil {
347				s.Close()
348			}
349			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
350		}
351		if !strings.Contains(err.Error(), `"`+emptyID+`"`) ||
352			!strings.Contains(err.Error(), "has no actions") {
353			t.Fatalf("error must name %s and explain empty actions: %v", emptyID, err)
354		}
355		// 打开失败意味着连正常提案/凭据也查不到：不存在能返回部分结果的句柄。
356		if _, oerr := Open(path); !errors.Is(oerr, ErrStateCorrupt) {
357			t.Fatalf("querying %s must not succeed on a file that also contains %s: %v",
358				goodID, emptyID, oerr)
359		}
360		if got, _ := os.ReadFile(path); string(got) != string(raw) {
361			t.Fatalf("corrupt file was modified")
362		}
363	}
