412	// TestNoActionUnexecutedProposalUsageUnchanged：无动作提案尚未执行时的
413	// 现有用法保持不变——登记/创建投票、正常查询、按既有规则投票计票都照常；
414	// 通过后执行继续以没有动作为由拒绝，状态、余额与凭据记录保持原样。
415	func TestNoActionUnexecutedProposalUsageUnchanged(t *testing.T) {
416		// 登记来源：可登记（含空切片与 nil 等价重试）、可查询，执行拒绝且不留痕。
417		store, path := openTempStore(t, 100)
418		defer store.Close()
419		if existed, err := store.Register("gip-nil", 0, nil); err != nil || existed {
420			t.Fatalf("register nil actions: existed=%v err=%v", existed, err)
421		}
422		if existed, err := store.Register("gip-nil", 0, []string{}); err != nil || !existed {
423			t.Fatalf("empty-slice retry: existed=%v err=%v", existed, err)
424		}
425		rec, ok, err := store.Proposal("gip-nil")
426		if err != nil || !ok || rec.State != "passed" || len(rec.Actions) != 0 {
427			t.Fatalf("query no-action proposal: %+v ok=%v err=%v", rec, ok, err)
428		}
429		if rcpt, eerr := store.Execute("gip-nil", 0); !errors.Is(eerr, ErrExecutionRejected) ||
430			!strings.Contains(eerr.Error(), "no actions") || rcpt != nil {
431			t.Fatalf("execute register no-action rcpt=%+v err=%v", rcpt, eerr)
432		}
433		if bal, _ := store.TreasuryBalance(); bal != 100 {
434			t.Fatalf("treasury changed: %d", bal)
435		}
436		if rs, _ := store.Receipts(); len(rs) != 0 {
437			t.Fatalf("receipt created for no-action rejection: %+v", rs)
438		}
439		rec, _, _ = store.Proposal("gip-nil")
440		if rec.State != "passed" {
441			t.Fatalf("state changed after rejected execute: %s", rec.State)
442		}
443	
444		// 投票来源：无动作也可创建、投票与计票（按既有规则通过），执行拒绝。
445		in := baseVoteInput("gip-vote-empty")
446		in.Actions = []string{}
447		mustCreateVote(t, store, in)
448		if _, err := store.CastVote("gip-vote-empty", "alice", true, 150); err != nil {
449			t.Fatal(err)
450		}
451		tally, err := store.TallyVote("gip-vote-empty", 200)
452		if err != nil || !tally.Passed {
453			t.Fatalf("tally=%+v err=%v", tally, err)
454		}
455		if rcpt, eerr := store.Execute("gip-vote-empty", 300); !errors.Is(eerr, ErrExecutionRejected) ||
456			!strings.Contains(eerr.Error(), "no actions") || rcpt != nil {
457			t.Fatalf("execute vote no-action rcpt=%+v err=%v", rcpt, eerr)
458		}
459		vp, ok, err := store.VoteProposal("gip-vote-empty")
460		if err != nil || !ok || vp.State != "passed" {
461			t.Fatalf("vote proposal state after rejected execute: %+v ok=%v err=%v", vp, ok, err)
462		}
463		// 再次计票返回首次结论，不转账。
464		again, err := store.TallyVote("gip-vote-empty", 201)
465		if err != nil || !again.Passed {
466			t.Fatalf("retally=%+v err=%v", again, err)
467		}
468		if bal, _ := store.TreasuryBalance(); bal != 100 {
469			t.Fatalf("treasury changed after no-action vote flow: %d", bal)
470		}
471	
472		// 重开：未执行的无动作提案（两种来源）仍是合法状态，查询不受影响。
473		store.Close()
474		reopened, err := Open(path)
475		if err != nil {
476			t.Fatalf("reopen: %v", err)
477		}
478		defer reopened.Close()
479		if rec, ok, _ := reopened.Proposal("gip-nil"); !ok || rec.State != "passed" {
480			t.Fatalf("register proposal after reopen: %+v ok=%v", rec, ok)
481		}
482		if vp, ok, _ := reopened.VoteProposal("gip-vote-empty"); !ok || vp.State != "passed" {
483			t.Fatalf("vote proposal after reopen: %+v ok=%v", vp, ok)
484		}
485		if bal, _ := reopened.TreasuryBalance(); bal != 100 {
486			t.Fatalf("treasury after reopen: %d", bal)
487		}
488		if rs, _ := reopened.Receipts(); len(rs) != 0 {
489			t.Fatalf("receipts after reopen: %+v", rs)
490		}
491	}
