517		if bal, _ := reopened.TreasuryBalance(); bal != 0 {
518			t.Fatalf("treasury after reopen=%d, want 0", bal)
519		}
520		if snap, err := reopened.BalanceSnapshot(); err != nil || snap.Treasury != 0 || snap.Balances["acct"] != 100 {
521			t.Fatalf("snapshot=%+v err=%v", snap, err)
522		}
523		again, err := reopened.Execute("gip-zero", 999)
524		if err != nil || again.Order != first.Order || again.ExecutedAt != first.ExecutedAt ||
525			len(again.Actions) != 2 {
