func TestScratchTamper(t *testing.T) {
	store, path := openTempStore(t, 1000)
	mustRegister(t, store, "gip-lz", 0, "transfer:audits:007")
	if _, err := store.Execute("gip-lz", 0); err != nil { t.Fatal(err) }
	store.Close()

	// zero leading: reject on first execute
	s2, _ := openTempStore(t, 50)
	mustRegister(t, s2, "gip-zero", 0, "transfer:audits:000", "transfer:audits:5")
	_, zerr := s2.Execute("gip-zero", 0)
	t.Logf("zero execute err=%v isRej=%v", zerr, errors.Is(zerr, ErrExecutionRejected))
	if b, _ := s2.TreasuryBalance(); b != 50 { t.Fatalf("partial transfer: %d", b) }
	if rs, _ := s2.Receipts(); len(rs) != 0 { t.Fatalf("receipt after zero: %v", rs) }
	s2.Close()

	// tamper receipt action text 007 -> 7
	raw, _ := os.ReadFile(path)
	s := string(raw)
	if !strings.Contains(s, "transfer:audits:007") { t.Fatal("raw text not on disk") }
	s = strings.Replace(s, `"action": "transfer:audits:007"`, `"action": "transfer:audits:7"`, 1)
	if err := os.WriteFile(path, []byte(s), 0o600); err != nil { t.Fatal(err) }
	before, _ := os.ReadFile(path)
	_, oerr := Open(path)
	t.Logf("open tampered err=%v isCorrupt=%v", oerr, errors.Is(oerr, ErrStateCorrupt))
	after, _ := os.ReadFile(path)
	t.Logf("file unchanged=%v", string(before)==string(after))

	// also dump one state doc to see JSON key formatting
	var doc map[string]any
	_ = json.Unmarshal(raw, &doc)
}
EOF
